mapper.select:
select c.id as customer_id, c.name as customer_name, c.owner_user, u.user_name as owner_name, a.id, ifnull(a.balance, 0) as balance, ifnull(a.frozen_amount, 0) as frozen_amount, ifnull(a.balance, 0) - ifnull(a.frozen_amount, 0) as available_balance, ifnull(a.total_recharge, 0) as total_recharge, ifnull(a.total_deduct, 0) as total_deduct, ifnull(a.total_refund, 0) as total_refund, a.last_flow_time, ifnull(a.status, 1) as status, a.create_time from crm_customer c left join crm_customer_account a on a.customer_id = c.id left join sys_user u on c.owner_user = u.user_id
c.deleted = 0
and c.name like concat('%', #{customerName}, '%')
and c.owner_user = #{params.ownerUser}
and c.owner_user = #{ownerUser}
and ifnull(a.balance, 0) > 0
and ifnull(a.balance, 0) = 0
and ifnull(a.balance, 0) >= #{minBalance}
and ifnull(a.balance, 0) <= #{maxBalance}
and ifnull(a.status, 1) = #{status}
order by ifnull(a.balance, 0) desc, c.id desc
